        }
    }
    for (int i = 1; i <= k; i++){
        int x;
        cin >> x;
        g.add(t * n, x - 1, 1, 0, 0);
    }
    for (int i = 1; i <= m; i++){
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        for (int j = 0; j < t - 1; j++){
            int v1 = j * n + u;
            int v2 = (j + 1) * n + v;
            for (int q = 0; q < k; q++){
                if (q == 0) g.add(v1, v2, 1, 0, d);
                else if (q == 1) g.add(v1, v2, 1, 0, 4 * d);
                else   g.add(v1, v2, 1, 0, d * (2 * q + 1));
            }
            v1 = j * n + v;
            v2 = (j + 1) * n + u;
            for (int q = 0; q < k; q++){
                if (q == 0) g.add(v1, v2, 1, 0, d);
                else if (q == 1) g.add(v1, v2, 1, 0, 4 * d);
                else   g.add(v1, v2, 1, 0, d * (2 * q + 1));
            }
        }
    }
    cout << (g.max_flow_min_cost()).S;
